"""Full-format HTTP ingestion smoke for the deterministic 120-person corpus.

Runs explicitly in Synthetic Corpus CI. Never uploads personal documents.
"""
from __future__ import annotations

import os
from pathlib import Path

import pytest
from fastapi.testclient import TestClient

from backend.app import create_app


def test_all_120_docx_and_120_pdf_through_real_hr_api(tmp_path):
    location = os.environ.get('HUIYAN_SYNTHETIC_CORPUS')
    if not location:
        pytest.skip('Full synthetic corpus is generated by the dedicated CI workflow')
    root = Path(location)
    docs = sorted((root / 'docx').glob('*.docx'))
    pdfs = sorted((root / 'pdf-text').glob('*.pdf'))
    assert len(docs) == len(pdfs) == 120
    app = create_app(tmp_path / 'data')
    with TestClient(app) as client:
        task = client.post('/api/tasks', json={
            'title': '240份多格式虚构简历兼容性验收',
            'description': '仅测试文件导入和可复核证据',
            'required': ['客户开发'],
        })
        assert task.status_code == 200
        tid = task.json()['id']
        imported = 0
        for collection in (docs, pdfs):
            for offset in range(0, len(collection), 10):
                files = [
                    ('files', (file.name, file.read_bytes(),
                     'application/pdf' if file.suffix == '.pdf'
                     else 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'))
                    for file in collection[offset:offset + 10]
                ]
                response = client.post(f'/api/tasks/{tid}/resumes', files=files)
                assert response.status_code == 200, response.text
                info = response.json()
                assert info['imported'] == len(files), info
                assert not info['issues'], info
                imported += info['imported']
        assert imported == 240
        records = client.get(f'/api/tasks/{tid}/resumes')
        assert records.status_code == 200
        assert len(records.json()) == 240
        # Test actual stored original and parsed pages, not just the parser.
        one = records.json()[0]
        detail = client.get(f'/api/tasks/{tid}/resumes/{one["id"]}').json()
        assert any(p['text'].strip() for p in detail['pages'])
        original = client.get(f'/api/tasks/{tid}/resumes/{one["id"]}/original')
        assert original.status_code == 200
        assert original.content
        run = client.post(f'/api/tasks/{tid}/runs', json={'name': '多格式筛选验收'})
        assert run.status_code == 200, run.text
        results = client.get(f'/api/tasks/{tid}/runs/{run.json()["id"]}/results')
        assert results.status_code == 200
        assert results.json()['total'] == 240
